insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Residus verts', 'Les residus verts sont ramasses avec les matieres organiques, au bac brun: chaque semaine de mai a novembre, une semaine sur deux l''hiver. Les branches ont leur propre collecte.', null, null), (current_setting('app.id')::bigint, 'en', 'Green waste', 'Green waste is picked up with organics, in the brown bin: weekly from May to November, every other week in winter. Branches have their own pickup.', null, null), (current_setting('app.id')::bigint, 'zh', '庭院废料', '庭院废料随有机垃圾一起放入棕桶：5 月至 11 月每周收，冬季隔周收。树枝另有专门收集。', null, null);
