insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Papier', 'Le papier (journaux, revues, papier d''imprimante) va au bac bleu, sauf s''il est souille, cire ou plastifie. Deposez-le en vrac dans le bac, pas dans un sac de plastique.', null, null), (current_setting('app.id')::bigint, 'en', 'Paper', 'Paper (newspaper, magazines, printer paper) goes in the blue bin, unless soiled, waxed or laminated. Put it in the bin loose, not in a plastic bag.', null, null), (current_setting('app.id')::bigint, 'zh', '纸张', '纸张（报纸、杂志、打印纸）放入蓝桶；脏污、上蜡或覆膜的纸除外。请散放入桶内，不要装在塑料袋里。', null, null);
