insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Verre', 'Le verre va au bac bleu. Pas les vitres, les fenetres, les verres a boire, la vaisselle ni les miroirs. Deposez-le en vrac dans le bac, pas dans un sac de plastique.', null, null), (current_setting('app.id')::bigint, 'en', 'Glass', 'Glass goes in the blue bin. Not glass panes, windows, drinking glasses, dishes or mirrors. Put it in the bin loose, not in a plastic bag.', null, null), (current_setting('app.id')::bigint, 'zh', '玻璃', '玻璃放入蓝桶。窗玻璃、窗户、玻璃杯、餐具和镜子除外。请散放入桶内，不要装在塑料袋里。', null, null);
