insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Plastiques', 'Tous les contenants de plastique, ainsi que les plastiques nos 1, 2, 3, 4, 5 et 7, vont au bac bleu. Pas le plastique no 6. Deposez-le en vrac dans le bac, pas dans un sac de plastique.', null, null), (current_setting('app.id')::bigint, 'en', 'Plastic', 'All plastic containers, as well as plastics #1, 2, 3, 4, 5 and 7, go in the blue bin. Not #6 plastic. Put it in the bin loose, not in a plastic bag.', null, null), (current_setting('app.id')::bigint, 'zh', '塑料', '所有塑料容器，以及 1、2、3、4、5、7 号塑料，放入蓝桶。6 号塑料除外。请散放入桶内，不要装在塑料袋里。', null, null);
