insert into sorting_item_translation (item_id, language_code, name, instruction, location, availability) values (current_setting('app.id')::bigint, 'fr', 'Metal', 'Le metal (boites de conserve, etc.) va au bac bleu. Pas les gros objets en metal. Deposez-le en vrac dans le bac, pas dans un sac de plastique.', null, null), (current_setting('app.id')::bigint, 'en', 'Metal', 'Metal (food cans, etc.) goes in the blue bin. Not large metal items. Put it in the bin loose, not in a plastic bag.', null, null), (current_setting('app.id')::bigint, 'zh', '金属', '金属（罐头盒等）放入蓝桶。大型金属物品除外。请散放入桶内，不要装在塑料袋里。', null, null);
